@@ -47,6 +47,11 @@ install_docker() {
 	PKG_MANAGER=${PKG_MANAGER_PATH##*/}

 	case "$PKG_MANAGER" in
+	apk)
+		PACKAGES=$(echo $PACKAGES | sed -r -e 's/-ce|[.]io//g')
+		$SUDO apk add ${PACKAGES}
+		;;
+	
 	apt-get)
 		$SUDO apt-get update
 		$SUDO apt-get -y install apt-transport-https ca-certificates curl gnupg
